from collections import Counter

def block_analysis(input_grid, bi, bj, block_size=3, offset_r=0, offset_c=0):
    if bi*block_size + block_size*offset_r >= len(input_grid):
        return None
    if bj*block_size + block_size*offset_c >= len(input_grid[0]):
        return None
    block = []
    for ki in range(block_size):
        for kj in range(block_size):
            r = bi*block_size + offset_r*block_size + ki*block_size
            c = bj*block_size + offset_c*block_size + kj*block_size
            block.append(input_grid[r][c])
    c = Counter(block)
    return max(c.items(), key=lambda x: (x[1], -x[0]))[0], c

