# Let me try: count how many times value X appears, minus something for background
# Actually, what if the pattern is: for each block, count every value and for each count
# also look at how "clustered" that value is (e.g., number of 2x2 same-value blocks)

def cluster_score(input_grid, bi, bj, val):
    """Count clusters of val - a 3-cell connected line or more counts as 1 cluster"""
    cl = set()  # cells with val in this block
    for ki in range(3):
        for kj in range(3):
            if input_grid[bi*3 + ki][bj*3 + kj] == val:
                cl.add((ki, kj))

    # Count local clusters
    clusters = 0
    seen = set()
    for (ki, kj) in cl:
        if (ki, kj) in seen:
            continue
        cl_new = set()
        queue = [(ki, kj)]
        while queue:
            (r, c) = queue.pop()
            if (r, c) in cl_new:
                continue
            cl_new.add((r, c))
            for (nr, nc) in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if (nr, nc) in cl and (nr, nc) not in cl_new:
                    queue.append((nr, nc))
        if cl_new:
            seen.update(cl_new)
            clusters += 1
    return clusters

